class FileSystem {
    private java.util.Map<String, Integer> map = new java.util.HashMap<>();
    public FileSystem() { map.put("", 0); }
    public boolean createPath(String path, int value) {
        if (map.containsKey(path)) return false;
        String parent = path.substring(0, path.lastIndexOf('/'));
        if (!map.containsKey(parent)) return false;
        map.put(path, value);
        return true;
    }
    public int get(String path) {
        return map.getOrDefault(path, -1);
    }
}

import java.util.*;

class FileSystem {
    private Map<String, Integer>[] children;
    private int[] values;
    private int cnt;
    public FileSystem() {
        children = new HashMap[100001];
        values = new int[100001];
        Arrays.fill(values, -1);
        children[0] = new HashMap();
        cnt = 1;
    }
    public boolean createPath(String path, int value) {
        String[] parts = path.split("/");
        int node = 0;
        for (int i = 1; i < parts.length - 1; i++) {
            if (!children[node].containsKey(parts[i])) return false;
            node = children[node].get(parts[i]).intValue();
        }
        String last = parts[parts.length - 1];
        if (children[node].containsKey(last)) return false;
        int newNode = cnt++;
        children[newNode] = new HashMap();
        values[newNode] = value;
        children[node].put(last, newNode);
        return true;
    }
    public int get(String path) {
        String[] parts = path.split("/");
        int node = 0;
        for (int i = 1; i < parts.length; i++) {
            if (!children[node].containsKey(parts[i])) return -1;
            node = children[node].get(parts[i]).intValue();
        }
        return values[node];
    }
}
